{
  "faqs": [
    {
      "question": "What is the refund window?",
      "answer": "Refunds can be requested within 30 days of purchase."
    },
    {
      "question": "How long does a refund take to arrive?",
      "answer": "Refunds are issued within 2 business days of approval, but the bank may take an additional 5-10 business days to process the refund."
    },
    {
      "question": "Can I get a refund for Acme Pay transactions?",
      "answer": "Yes, refunds for Acme Pay transactions can be requested within 30 days of the purchase."
    },
    {
      "question": "What payment methods does Acme Pay support?",
      "answer": "Acme Pay supports payments in USD, EUR, GBP, and INR."
    },
    {
      "question": "How do I request a refund for Acme Billing Pro?",
      "answer": "To request a refund for Acme Billing Pro, please submit your request through the Customer Portal within 30 days of purchase."
    },
    {
      "question": "Are there any fees associated with refunds?",
      "answer": "No, there are no fees associated with processing refunds for any of our products."
    },
    {
      "question": "How can I check the status of my refund?",
      "answer": "You can check the status of your refund in the Customer Portal under the Billing section."
    },
    {
      "question": "What happens if my refund is not processed?",
      "answer": "If your refund is not processed within the expected timeframe, please reach out for assistance through the Customer Portal."
    },
    {
      "question": "How long are my payment transaction records kept?",
      "answer": "Payment transaction records are kept for 7 years in accordance with regulatory requirements."
    },
    {
      "question": "What should I do if I'm locked out of my account?",
      "answer": "If you are locked out, support will verify your identity using two of three factors and send a reset link that expires in 24 hours."
    },
    {
      "question": "Can I reset my MFA if I no longer have access to my device?",
      "answer": "Yes, you can reset your MFA from the Customer Portal under Account > Security, or contact support for assistance."
    },
    {
      "question": "What is the session timeout for the Customer Portal?",
      "answer": "Sessions in the Customer Portal expire after 15 minutes of inactivity."
    },
    {
      "question": "How do I receive notifications about my billing?",
      "answer": "You can receive notifications via email and SMS through Acme Notify."
    },
    {
      "question": "Are my credit card details stored by Acme?",
      "answer": "No, Acme never stores the full card number; all cards are tokenized by the Payment Gateway for security."
    },
    {
      "question": "How long are customer application logs retained?",
      "answer": "Customer application logs are retained for 13 months."
    }
  ]
}
